"""Score the wallet-memory steps: VmHWM after n inputs per arm (medians [range] of the runs, kB), and each arm's
change against the arm before it and against the first arm, with an overlap check (disjoint ranges = "no overlap").
Arms are the run labels in mem_f2.csv without their "_r<k>" round suffix, in the order given.
usage: python3 wallet_mem_steps.py <mem_f2.csv> dot3 f2-1 f2-2 f2-3"""
import collections, csv, statistics, sys

if len(sys.argv) < 4:
    sys.exit(__doc__)
path, arms = sys.argv[1], sys.argv[2:]
v = collections.defaultdict(list)
for r in csv.DictReader(open(path)):
    if r["n"] in ("8", "32", "128"):
        v[(r["arm"].rsplit("_r", 1)[0], r["n"])].append(int(r["VmHWM_kB"]))
med = lambda a, n: statistics.median(v[(a, n)])

def cmp(a, b, n):
    x, y = v[(a, n)], v[(b, n)]
    disjoint = max(x) < min(y) or min(x) > max(y)
    return f"{(med(a, n) / med(b, n) - 1) * 100:+.1f}% ({'no overlap' if disjoint else 'overlap'})"

for n in ("8", "32", "128"):
    print(f"n={n}")
    for i, a in enumerate(arms):
        line = f"  {a:6} {med(a, n):>11,.0f} [{min(v[(a, n)]):,}-{max(v[(a, n)]):,}] kB, runs {len(v[(a, n)])}"
        if i:
            line += f"; against {arms[i - 1]} {cmp(a, arms[i - 1], n)}; against {arms[0]} {cmp(a, arms[0], n)}"
        print(line)
